#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package MQTTnet@4.3.2.930 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable using System; using System.Threading.Tasks; using MQTTnet; using MQTTnet.Server;  namespace MQTTNetDemo {     /// <summary>     /// MQTT服务器测试     /// </summary>     public class Program     {         public static async Task Main(string[] args)         {             Console.WriteLine("MQTT Server Test");             Console.WriteLine("===============");              try             {                 var factory = new MqttFactory();                 var server = factory.CreateMqttServer(new MqttServerOptions());                  await server.StartAsync();                 Console.WriteLine("✅ MQTT Server started!");                 Console.WriteLine("   Listening on port 1883");                 Console.WriteLine("   Use a separate MQTT client to connect to this server.");                  Console.WriteLine("\nPress any key to stop the server...");                 Console.ReadKey();                  await server.StopAsync();                 Console.WriteLine("✅ MQTT Server stopped!");             }             catch (Exception ex)             {                 Console.WriteLine($"❌ Error: {ex.Message}");                 Console.WriteLine($"   Stack trace: {ex.StackTrace}");                 Console.ReadKey();             }         }     } }
